336			}
337		case "pypi":
338			return "", strings.ToLower(strings.ReplaceAll(n, "_", "-")), ""
339		case "golang":
340			if last := strings.LastIndex(n, "/"); last >= 0 {
341				return n[:last], n[last+1:], ""
342			}
343		case "npm":
344			if strings.HasPrefix(n, "@") {
